#!/usr/bin/env python3
"""
Supervised Edge Control
========================

Supervised web browsing for Ashe using Microsoft Edge automation.

CRITICAL: All web access requires active user supervision per Constitution.
Ashe cannot browse autonomously - user must approve each action.

Author: Rickey Jay Bennett II
Version: 1.0.0
"""

import time
from typing import Optional, Dict, Any, List
from pathlib import Path

# Optional imports
HAS_SELENIUM = False
try:
    from selenium import webdriver
    from selenium.webdriver.edge.service import Service
    from selenium.webdriver.edge.options import Options
    from selenium.webdriver.common.by import By
    from selenium.webdriver.support.ui import WebDriverWait
    from selenium.webdriver.support import expected_conditions as EC
    HAS_SELENIUM = True
except ImportError:
    pass


class SupervisedEdgeControl:
    """
    Supervised web browsing using Microsoft Edge.

    All actions require user approval. Ashe cannot browse autonomously.
    """

    def __init__(self, headless: bool = False):
        """
        Initialize supervised browser control.

        Args:
            headless: Run browser in headless mode (not recommended for supervision)
        """
        if not HAS_SELENIUM:
            raise RuntimeError("Selenium not installed. Run: pip install selenium")

        self.headless = headless
        self.driver: Optional[webdriver.Edge] = None
        self.supervision_enabled = True  # Always true per Constitution

        if headless:
            print("WARNING: Headless mode makes supervision difficult")

        print("Supervised Edge Control initialized")
        print("REMINDER: All web actions require user approval per Constitution")

    def start_browser(self) -> bool:
        """
        Start Edge browser.

        Returns:
            True if successful
        """
        if self.driver is not None:
            print("Browser already running")
            return True

        try:
            options = Options()
            if self.headless:
                options.add_argument("--headless")

            # Additional options for better control
            options.add_argument("--disable-blink-features=AutomationControlled")
            options.add_experimental_option("excludeSwitches", ["enable-automation"])

            self.driver = webdriver.Edge(options=options)
            print("✓ Edge browser started")
            return True

        except Exception as e:
            print(f"ERROR: Failed to start browser: {e}")
            print("Ensure Microsoft Edge WebDriver is installed")
            return False

    def navigate(self, url: str, wait_for_user: bool = True) -> Dict[str, Any]:
        """
        Navigate to URL with user supervision.

        Args:
            url: URL to navigate to
            wait_for_user: Wait for user approval

        Returns:
            Result dict with status and page info
        """
        if self.driver is None:
            if not self.start_browser():
                return {"error": "Failed to start browser"}

        # Request user approval
        if wait_for_user and self.supervision_enabled:
            print(f"\nAshe requests permission to navigate to: {url}")
            response = input("Approve? (yes/no): ").strip().lower()
            if response not in ['yes', 'y']:
                return {"status": "denied", "message": "User denied navigation"}

        try:
            self.driver.get(url)
            time.sleep(2)  # Allow page to load

            result = {
                "status": "success",
                "url": self.driver.current_url,
                "title": self.driver.title,
                "timestamp": time.time()
            }

            print(f"✓ Navigated to: {result['title']}")
            return result

        except Exception as e:
            return {"error": str(e)}

    def get_page_content(self) -> Dict[str, Any]:
        """
        Get current page content.

        Returns:
            Dict with page text and metadata
        """
        if self.driver is None:
            return {"error": "Browser not started"}

        try:
            result = {
                "url": self.driver.current_url,
                "title": self.driver.title,
                "text": self.driver.find_element(By.TAG_NAME, "body").text,
                "timestamp": time.time()
            }
            return result
        except Exception as e:
            return {"error": str(e)}

    def search_on_page(self, query: str) -> Dict[str, Any]:
        """
        Search for text on current page.

        Args:
            query: Text to search for

        Returns:
            Search results
        """
        if self.driver is None:
            return {"error": "Browser not started"}

        try:
            page_text = self.driver.find_element(By.TAG_NAME, "body").text

            # Simple text search
            if query.lower() in page_text.lower():
                # Find context around match
                idx = page_text.lower().find(query.lower())
                context_start = max(0, idx - 100)
                context_end = min(len(page_text), idx + len(query) + 100)
                context = page_text[context_start:context_end]

                result = {
                    "found": True,
                    "query": query,
                    "context": context,
                    "url": self.driver.current_url
                }
            else:
                result = {
                    "found": False,
                    "query": query,
                    "url": self.driver.current_url
                }

            return result

        except Exception as e:
            return {"error": str(e)}

    def click_element(self, selector: str, wait_for_user: bool = True) -> Dict[str, Any]:
        """
        Click an element with user supervision.

        Args:
            selector: CSS selector for element
            wait_for_user: Wait for user approval

        Returns:
            Result dict
        """
        if self.driver is None:
            return {"error": "Browser not started"}

        # Request user approval
        if wait_for_user and self.supervision_enabled:
            print(f"\nAshe requests permission to click element: {selector}")
            response = input("Approve? (yes/no): ").strip().lower()
            if response not in ['yes', 'y']:
                return {"status": "denied", "message": "User denied click action"}

        try:
            element = WebDriverWait(self.driver, 10).until(
                EC.element_to_be_clickable((By.CSS_SELECTOR, selector))
            )
            element.click()

            return {
                "status": "success",
                "action": "click",
                "selector": selector
            }

        except Exception as e:
            return {"error": str(e)}

    def take_screenshot(self, filepath: Optional[str] = None) -> Dict[str, Any]:
        """
        Take screenshot of current page.

        Args:
            filepath: Path to save screenshot

        Returns:
            Result dict with filepath
        """
        if self.driver is None:
            return {"error": "Browser not started"}

        try:
            if filepath is None:
                filepath = f"screenshot_{int(time.time())}.png"

            self.driver.save_screenshot(filepath)

            return {
                "status": "success",
                "filepath": filepath,
                "url": self.driver.current_url
            }

        except Exception as e:
            return {"error": str(e)}

    def close_browser(self):
        """Close the browser."""
        if self.driver is not None:
            try:
                self.driver.quit()
                self.driver = None
                print("✓ Browser closed")
            except Exception as e:
                print(f"Warning: Error closing browser: {e}")


if __name__ == "__main__":
    # Test supervised browsing
    print("Testing Supervised Edge Control...\n")

    control = SupervisedEdgeControl()

    # Test navigation
    result = control.navigate("https://www.wikipedia.org")
    print(f"\nNavigation result: {result}")

    if result.get("status") == "success":
        # Get page content
        content = control.get_page_content()
        print(f"\nPage title: {content.get('title')}")
        print(f"Content length: {len(content.get('text', ''))}")

        # Search on page
        search = control.search_on_page("Wikipedia")
        print(f"\nSearch result: {search.get('found')}")

    # Close
    input("\nPress Enter to close browser...")
    control.close_browser()

