echo ========================================================================
echo              ASHE - BUILD EXECUTABLE PACKAGE
echo ========================================================================
echo.
echo This script will create standalone executables for Ashe using PyInstaller.
echo.
echo Prerequisites:
echo   - Python 3.8+ installed
echo   - PyInstaller installed (pip install pyinstaller)
echo   - All dependencies installed (pip install -r requirements.txt)
echo.
echo ========================================================================
pause

echo.
echo Checking Python...
python --version >nul 2>&1
if errorlevel 1 (
    echo ERROR: Python not found
    pause
    exit /b 1
)
python --version

echo.
echo Checking PyInstaller...
pip show pyinstaller >nul 2>&1
