echo.
echo ========================================================================
echo BUILDING EXECUTABLES
echo ========================================================================

cd %~dp0

echo.
echo Building with PyInstaller...
pyinstaller ashe.spec

if errorlevel 1 (
    echo.
    echo ERROR: Build failed
    pause
    exit /b 1
)

echo.
echo ========================================================================
echo BUILD COMPLETE
echo ========================================================================
echo.
echo Executables created in: dist\ashe\
echo.
