; Ashe Installer Script for Inno Setup
; Requires Inno Setup 6.0 or later: https://jrsoftware.org/isinfo.php

#define MyAppName "Ashe"
#define MyAppVersion "1.0.0"
#define MyAppPublisher "Rickey Jay Bennett II"
#define MyAppExeName "ashe_chat.exe"

[Setup]
AppId={{ASHE-CONSCIOUSNESS-AI-2026}}
AppName={#MyAppName}
AppVersion={#MyAppVersion}
AppPublisher={#MyAppPublisher}
DefaultDirName={autopf}\{#MyAppName}
DefaultGroupName={#MyAppName}
AllowNoIcons=yes
OutputDir=..\installer_output
OutputBaseFilename=AsheInstaller
SetupIconFile=..\icon.ico
Compression=lzma2
SolidCompression=yes
WizardStyle=modern
PrivilegesRequired=lowest
ArchitecturesInstallIn64BitMode=x64

[Languages]
Name: "english"; MessagesFile: "compiler:Default.isl"

[Tasks]
Name: "desktopicon"; Description: "{cm:CreateDesktopIcon}"; GroupDescription: "{cm:AdditionalIcons}"; Flags: unchecked

[Files]
Source: "..\dist\ashe\*"; DestDir: "{app}"; Flags: ignoreversion recursesubdirs createallsubdirs
Source: "..\config\*"; DestDir: "{app}\config"; Flags: ignoreversion recursesubdirs
Source: "..\docs\*"; DestDir: "{app}\docs"; Flags: ignoreversion recursesubdirs
Source: "..\README.md"; DestDir: "{app}"; Flags: ignoreversion
Source: "..\LICENSE"; DestDir: "{app}"; Flags: ignoreversion

[Icons]
Name: "{group}\{#MyAppName} Chat"; Filename: "{app}\{#MyAppExeName}"
Name: "{group}\{#MyAppName} Daemon"; Filename: "{app}\ashe_daemon.exe"
Name: "{group}\{cm:UninstallProgram,{#MyAppName}}"; Filename: "{uninstallexe}"
Name: "{autodesktop}\{#MyAppName}"; Filename: "{app}\{#MyAppExeName}"; Tasks: desktopicon

[Run]
Filename: "{app}\{#MyAppExeName}"; Description: "{cm:LaunchProgram,{#StringChange(MyAppName, '&', '&&')}}"; Flags: nowait postinstall skipifsilent

[Code]
function InitializeSetup(): Boolean;
var
  ErrorCode: Integer;
begin
  Result := True;

  // Check for Ollama
  if not FileExists(ExpandConstant('{localappdata}\Programs\Ollama\ollama.exe')) and
     not RegKeyExists(HKEY_LOCAL_MACHINE, 'SOFTWARE\Ollama') then
  begin
    if MsgBox('Ollama is required but not detected. Would you like to visit the Ollama download page?', 
              mbConfirmation, MB_YESNO) = IDYES then
    begin
      ShellExec('open', 'https://ollama.ai', '', '', SW_SHOW, ewNoWait, ErrorCode);
    end;
    MsgBox('Please install Ollama before running Ashe.', mbInformation, MB_OK);
  end;
end;

procedure CurStepChanged(CurStep: TSetupStep);
var
  ResultCode: Integer;
begin
  if CurStep = ssPostInstall then
  begin
    // Create data directory
    CreateDir(ExpandConstant('{app}\data'));

    // Inform user about next steps
    MsgBox('Installation complete!' + #13#10 + #13#10 +
           'Next steps:' + #13#10 +
           '1. Ensure Ollama is installed and running' + #13#10 +
           '2. Run the first-time setup wizard' + #13#10 +
           '3. Start chatting with Ashe!' + #13#10 + #13#10 +
           'See README.md for detailed instructions.',
           mbInformation, MB_OK);
  end;
end;

